// X-ray lens: a floating archipelago you can look through. Under the glass the same world is a blueprint with thousands of
// simulated players' trails flowing across it, and a tap sends one small player running a real trail to the flag.
// Art and data are all regenerated by concepts/blender/about/xray.
import './xray.css'
import type { AboutCtx } from '../types'
import { POSTER } from './poster'
import { MAIN, OVER_FRAG, OVER_VERT, VERT } from './shaders'

const TXT = {
  label: {
    en: 'A floating island world seen through a glass lens. Under the lens the same world appears as a blueprint, with the trails of thousands of simulated players flowing across it.',
    ar: 'عالم من جزر عائمة تحت عدسة زجاجية. تحت العدسة يظهر العالم نفسه مخططاً هندسياً، تسري فوقه مسارات آلاف اللاعبين المحاكَين.',
  },
  play: { en: 'Send a player to the flag', ar: 'أرسل لاعباً إلى الراية' },
  trails: { en: 'Player trails', ar: 'مسارات اللاعبين' },
  nav: { en: 'Navigation mesh', ar: 'شبكة الملاحة' },
  contours: { en: 'Contours', ar: 'خطوط الارتفاع' },
  wire: { en: 'Wireframe', ar: 'الهيكل الشبكي' },
  grid: { en: 'Survey grid', ar: 'شبكة المسح' },
  run: { en: 'One simulated player', ar: 'لاعب من المحاكاة' },
}
type Key = keyof typeof TXT

type Manifest = { routes: number[]; drift: [number, number][]; flag: [number, number]; flagTop: [number, number]; agents: number; seed: number; labels: string }
type Route = { n: number; x: Float32Array; y: Float32Array; s: Float32Array; d: Float32Array }

const clamp = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v))
const mix = (a: number, b: number, t: number) => a + (b - a) * t
const sstep = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}
const catmull = (p0: number, p1: number, p2: number, p3: number, t: number) =>
  0.5 * (2 * p1 + (p2 - p0) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (3 * p1 - p0 - 3 * p2 + p3) * t * t * t)

function shader(gl: WebGL2RenderingContext, type: number, src: string) {
  const s = gl.createShader(type)!
  gl.shaderSource(s, src)
  gl.compileShader(s)
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(`[xray] ${gl.getShaderInfoLog(s)}`)
  return s
}
function program(gl: WebGL2RenderingContext, vs: string, fs: string) {
  const p = gl.createProgram()!
  gl.attachShader(p, shader(gl, gl.VERTEX_SHADER, vs))
  gl.attachShader(p, shader(gl, gl.FRAGMENT_SHADER, fs))
  gl.linkProgram(p)
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(`[xray] ${gl.getProgramInfoLog(p)}`)
  return p
}

export default async function mount(ctx: AboutCtx) {
  const { section, stage, copy, lang, rtl, reduce, signal, base } = ctx
  const dir = `${base}about/xray/`
  const say = (k: Key) => TXT[k][lang]
  const small = () => stage.clientWidth < 820 || stage.clientWidth / Math.max(1, innerHeight) < 1.16 || innerHeight < 560

  // ------------------------------------------------------------------ the DOM
  const host = document.createElement('div')
  host.className = 'xr-host'
  const art = document.createElement('div')
  art.className = 'xr-art'
  art.setAttribute('role', 'img')
  art.setAttribute('aria-label', say('label'))
  const poster = document.createElement('img')
  poster.className = 'xr-poster'
  poster.alt = ''
  poster.src = POSTER
  const canvas = document.createElement('canvas')
  canvas.className = 'xr-canvas'
  canvas.setAttribute('aria-hidden', 'true')
  art.append(poster, canvas)
  const tag = document.createElement('div')
  tag.className = 'xr-tag'
  tag.setAttribute('aria-hidden', 'true')
  const tagText = document.createElement('span')
  tag.append(tagText)
  const play = document.createElement('button')
  play.type = 'button'
  play.className = 'xr-play'
  play.textContent = say('play')
  const spacer = document.createElement('div')
  spacer.className = 'xr-spacer'
  host.append(art, tag, copy, spacer, play)
  copy.classList.add('xr-copy')
  stage.append(host)

  // The hero's blue and this sky are one colour, so slide up under the hero and let its bottom edge vanish.
  section.style.marginTop = '0px'
  const hero = document.querySelector<HTMLElement>('.a-hero')
  let measuredAt = -1
  const measureOverlap = () => {
    if (measuredAt === innerWidth) return
    measuredAt = innerWidth
    section.style.marginTop = '0px'
    if (!hero) return
    const gap = section.getBoundingClientRect().top - hero.getBoundingClientRect().bottom
    section.style.marginTop = `${-(gap + 40)}px`
  }
  measureOverlap()

  // ------------------------------------------------------------------ layout
  let stack = small()
  let pinned = false
  const setPin = (on: boolean) => {
    if (on === pinned) return
    pinned = on
    if (on) ctx.pin(1.15)
    else {
      section.style.height = ''
      stage.classList.remove('is-pinned')
    }
  }
  const CENTER_U = 0.69
  const worldHeight = (w: number) => Math.max(500, Math.min(760, w * 1.42))
  const ANCHOR = 0.45
  type Geo = { w: number; h: number; imgW: number; imgH: number; offX: number; offY: number; zoom: number }
  const geo: Geo = { w: 1, h: 1, imgW: 1, imgH: 1, offX: 0, offY: 0, zoom: 1 }
  let textRect = { l: 0, t: 0, r: 0, b: 0 }
  const layout = (p = lastP) => {
    const w = stage.clientWidth
    const h = stack ? host.clientHeight : stage.clientHeight
    geo.w = w
    geo.h = h
    if (stack) {
      const worldH = worldHeight(w)
      geo.imgH = worldH
      geo.imgW = worldH * (16 / 9)
      const u = rtl ? 1 - CENTER_U : CENTER_U
      geo.offX = clamp(w / 2 - u * geo.imgW, w - geo.imgW, 0)
      geo.offY = h - worldH
    } else {
      const zoom = 1.045 + (reduce ? 0 : 0.075 * sstep(0, 1, p))
      geo.zoom = zoom
      geo.imgW = Math.max(w, h * (16 / 9)) * zoom
      geo.imgH = geo.imgW * (9 / 16)
      // Narrower windows slide the art away from the text, so the boat's sail stays clear of it.
      const anchor = mix(0.24, ANCHOR, sstep(1.3, 1.6, w / Math.max(1, h)))
      const a = rtl ? 1 - anchor : anchor
      geo.offX = (w - geo.imgW) * a
      geo.offY = (h - geo.imgH) * mix(0.42, 0.72, reduce ? 0 : sstep(0, 1, p))
    }
    const hb = host.getBoundingClientRect()
    const cr = copy.getBoundingClientRect()
    textRect = { l: cr.left - hb.left, t: cr.top - hb.top, r: cr.right - hb.left, b: cr.bottom - hb.top }
    if (!ready) poster.style.cssText = `left:${geo.offX}px;top:${geo.offY}px;width:${geo.imgW}px;height:${geo.imgH}px;${rtl ? 'transform:scaleX(-1);' : ''}`
  }
  const uvToCss = (u: number, v: number): [number, number] => [(rtl ? 1 - u : u) * geo.imgW + geo.offX, v * geo.imgH + geo.offY]
  const cssToUv = (x: number, y: number): [number, number] => {
    const u = (x - geo.offX) / geo.imgW
    return [rtl ? 1 - u : u, (y - geo.offY) / geo.imgH]
  }

  let lastP = 0
  let ready = false
  setPin(!stack && !reduce)
  stage.classList.toggle('xr-stack', stack)
  host.classList.toggle('xr-stack', stack)
  stage.classList.toggle('xr-still-height', !stack && reduce)

  // ------------------------------------------------------------------ no WebGL2: a composed still made of the same pictures
  const gl = canvas.getContext('webgl2', { antialias: false, alpha: true, premultipliedAlpha: true, powerPreference: 'high-performance', depth: false, stencil: false })
  const still = () => {
    host.classList.add('xr-still')
    canvas.remove()
    poster.remove()
    const img = document.createElement('img')
    img.src = `${dir}world.webp`
    img.alt = ''
    img.className = 'xr-still-world'
    const glass = document.createElement('div')
    glass.className = 'xr-still-glass'
    glass.style.backgroundImage = `url(${dir}trails.webp), url(${dir}blueprint.webp)`
    art.append(img, glass)
    const place = () => {
      layout(0)
      img.style.cssText = `left:${geo.offX}px;top:${geo.offY}px;width:${geo.imgW}px;height:${geo.imgH}px;${rtl ? 'transform:scaleX(-1);' : ''}`
      const [cx, cy] = uvToCss(0.66, 0.5)
      const R = Math.min(geo.w * 0.2, geo.imgH * 0.26)
      const s = 1.15
      glass.style.cssText = `left:${cx - R}px;top:${cy - R}px;width:${2 * R}px;height:${2 * R}px;background-image:url(${dir}trails.webp),url(${dir}blueprint.webp);background-size:${geo.imgW * s}px ${geo.imgH * s}px;background-position:${R - 0.66 * geo.imgW * s}px ${R - 0.5 * geo.imgH * s}px;background-blend-mode:screen;${rtl ? 'transform:scaleX(-1);' : ''}`
    }
    place()
    addEventListener('resize', place, { signal })
  }
  if (!gl) {
    still()
    return () => {
      copy.classList.remove('xr-copy')
    }
  }

  // ------------------------------------------------------------------ GL
  const prog = program(gl, VERT, MAIN)
  const over = program(gl, OVER_VERT, OVER_FRAG)
  const U: Record<string, WebGLUniformLocation | null> = {}
  for (const n of ['uWorld', 'uBlue', 'uTrail', 'uTimeMap', 'uDepth', 'uOver', 'uFlow', 'uRes', 'uOff', 'uSize', 'uFlip', 'uLens', 'uTime', 'uPar', 'uLensOn', 'uMag', 'uMotion', 'uTop', 'uBot', 'uRimPx', 'uLod'])
    U[n] = gl.getUniformLocation(prog, n)
  const quad = gl.createBuffer()
  const vaoMain = gl.createVertexArray()
  gl.bindVertexArray(vaoMain)
  gl.bindBuffer(gl.ARRAY_BUFFER, quad)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  const aPos = gl.getAttribLocation(prog, 'aPos')
  gl.enableVertexAttribArray(aPos)
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0)

  // the overlay's batch: x, y, s, t, r, g, b, a, mode, depth
  const STRIDE = 10
  const MAXV = 60000
  const batch = new Float32Array(MAXV * STRIDE)
  const vbo = gl.createBuffer()
  const vaoOver = gl.createVertexArray()
  gl.bindVertexArray(vaoOver)
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo)
  gl.bufferData(gl.ARRAY_BUFFER, batch.byteLength, gl.DYNAMIC_DRAW)
  const attr = (name: string, size: number, offset: number) => {
    const l = gl.getAttribLocation(over, name)
    gl.enableVertexAttribArray(l)
    gl.vertexAttribPointer(l, size, gl.FLOAT, false, STRIDE * 4, offset * 4)
  }
  attr('aPos', 2, 0)
  attr('aSt', 2, 2)
  attr('aColor', 4, 4)
  attr('aMode', 2, 8)
  gl.bindVertexArray(null)

  const texUnits = { uWorld: 0, uBlue: 1, uTrail: 2, uTimeMap: 3, uDepth: 4, uOver: 5, uSprite: 6, uFlow: 7 } as const
  type TexName = keyof typeof texUnits
  const textures: Partial<Record<TexName, WebGLTexture>> = {}
  const blank = (name: TexName, rgba: number[]) => {
    const t = gl.createTexture()!
    gl.activeTexture(gl.TEXTURE0 + texUnits[name])
    gl.bindTexture(gl.TEXTURE_2D, t)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(rgba))
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    textures[name] = t
    return t
  }
  blank('uWorld', [214, 236, 240, 255])
  blank('uBlue', [1, 63, 59, 255])
  blank('uTrail', [0, 0, 0, 255])
  blank('uTimeMap', [0, 0, 0, 255])
  blank('uDepth', [128, 128, 128, 255])
  blank('uSprite', [0, 0, 0, 0])
  blank('uFlow', [0, 0, 0, 255])

  // the overlay target
  const OW = 2048
  const OH = 1152
  const overTex = blank('uOver', [0, 0, 0, 0])
  gl.activeTexture(gl.TEXTURE0 + texUnits.uOver)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, OW, OH, 0, gl.RGBA, gl.UNSIGNED_BYTE, null)
  const fbo = gl.createFramebuffer()
  gl.bindFramebuffer(gl.FRAMEBUFFER, fbo)
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, overTex, 0)
  gl.clearColor(0, 0, 0, 0)
  gl.clear(gl.COLOR_BUFFER_BIT)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)

  gl.useProgram(over)
  gl.uniform1i(gl.getUniformLocation(over, 'uSprite'), texUnits.uSprite)
  gl.uniform1i(gl.getUniformLocation(over, 'uDepth'), texUnits.uDepth)
  gl.useProgram(prog)
  for (const n of ['uWorld', 'uBlue', 'uTrail', 'uTimeMap', 'uDepth', 'uOver', 'uFlow'] as const) gl.uniform1i(U[n], texUnits[n])
  gl.uniform1f(U.uFlip, rtl ? 1 : 0)
  gl.uniform1f(U.uMag, 1.2)
  gl.uniform1f(U.uMotion, reduce ? 0 : 1)

  // ------------------------------------------------------------------ assets
  const texW = ctx.touch ? 1706 : 2560
  let manifest: Manifest | null = null
  const routes: Route[] = []
  const upload = (name: TexName, bmp: ImageBitmap, mips: boolean) => {
    if (signal.aborted) return
    gl.activeTexture(gl.TEXTURE0 + texUnits[name])
    gl.bindTexture(gl.TEXTURE_2D, textures[name]!)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, bmp)
    if (mips) {
      gl.generateMipmap(gl.TEXTURE_2D)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR)
    }
    bmp.close()
  }
  const loadImg = async (file: string, premul = false, fit = 0) => {
    const res = await fetch(dir + file, { signal })
    if (!res.ok) throw new Error(`[xray] ${file}: ${res.status}`)
    const size = fit ? { resizeWidth: fit, resizeHeight: Math.round((fit * 9) / 16), resizeQuality: 'high' as const } : {}
    return createImageBitmap(await res.blob(), { premultiplyAlpha: premul ? 'premultiply' : 'none', colorSpaceConversion: 'none', ...size })
  }
  const loadAll = async () => {
    // Beauty first: the moment it's up, the section looks right. The rest arrives under the glass, one texture per frame so nothing hitches.
    const worldBmp = await loadImg('world.webp', false, texW === 2560 ? 0 : texW)
    upload('uWorld', worldBmp, true)
    ready = true
    host.classList.add('is-ready')
    window.setTimeout(() => poster.remove(), 800)
    const man = (await (await fetch(`${dir}manifest.json`, { signal })).json()) as Manifest
    manifest = man
    buildDrift()
    const [blue, trail, time, depth, flow, sprite, bin] = await Promise.all([
      loadImg('blueprint.webp', false, texW === 2560 ? 0 : texW),
      loadImg('trails.webp', false, texW === 2560 ? 0 : Math.round((texW * 3) / 4)),
      loadImg('time.webp'),
      loadImg('depth.webp'),
      loadImg('flow.webp'),
      loadImg('runner.webp', true),
      fetch(`${dir}routes.bin`, { signal }).then(r => r.arrayBuffer()),
    ])
    const nextFrame = () => new Promise(r => requestAnimationFrame(r))
    upload('uDepth', depth, true)
    upload('uFlow', flow, false)
    await nextFrame()
    upload('uBlue', blue, true)
    await nextFrame()
    upload('uTrail', trail, true)
    await nextFrame()
    upload('uTimeMap', time, true)
    await nextFrame()
    upload('uSprite', sprite, true)
    const data = new Uint16Array(bin)
    let at = 0
    for (const n of man.routes) {
      const r: Route = { n, x: new Float32Array(n), y: new Float32Array(n), s: new Float32Array(n), d: new Float32Array(n) }
      for (let i = 0; i < n; i++) {
        r.x[i] = (data[at] / 65535) * 2560
        r.y[i] = (data[at + 1] / 65535) * 1440
        r.s[i] = (data[at + 2] / 65535) * 40
        r.d[i] = data[at + 3] / 65535
        at += 4
      }
      routes.push(r)
    }
    lensReady = true
    lensBorn = performance.now()
  }
  let lensReady = false
  let lensBorn = 0
  loadAll().catch(err => {
    if (!signal.aborted) console.error(err)
  })

  // ------------------------------------------------------------------ resizing
  let dpr = 1
  const resize = () => {
    const nextStack = small()
    if (nextStack !== stack) {
      stack = nextStack
      stage.classList.toggle('xr-stack', stack)
      host.classList.toggle('xr-stack', stack)
      setPin(!stack && !reduce)
      stage.classList.toggle('xr-still-height', !stack && reduce)
    }
    measureOverlap()
    if (stack) {
      spacer.style.height = `${worldHeight(stage.clientWidth) * 0.97}px`
    } else spacer.style.height = ''
    const cap = ctx.touch ? 1.6 : 2
    dpr = Math.min(devicePixelRatio || 1, cap)
    layout()
    const cw = Math.round(geo.w * dpr)
    const ch = Math.round(geo.h * dpr)
    if (canvas.width !== cw || canvas.height !== ch) {
      canvas.width = cw
      canvas.height = ch
    }
    dirty = true
  }
  let dirty = true
  const ro = new ResizeObserver(resize)
  ro.observe(stage)
  ro.observe(copy)
  addEventListener('resize', resize, { signal })
  resize()

  // ------------------------------------------------------------------ the lens's path
  // Drift points come from the Blender camera, so they are real places on the island. It wanders between them with no input.
  let drift: [number, number][] = []
  const buildDrift = () => {
    drift = manifest?.drift ?? []
  }
  const driftAt = (s: number): [number, number] => {
    const n = drift.length
    if (!n) return [0.68, 0.5]
    const f = ((s % n) + n) % n
    const i = Math.floor(f)
    const t = f - i
    const P = (k: number) => drift[(i + k + n) % n]
    return [catmull(P(-1)[0], P(0)[0], P(1)[0], P(2)[0], t), catmull(P(-1)[1], P(0)[1], P(1)[1], P(2)[1], t)]
  }

  const lens = { x: 0, y: 0, vx: 0, vy: 0, r: 0, tr: 0, on: 0, s: 0.4 }
  let placed = false
  const pointer = { x: 0, y: 0, active: false, last: -1e9, touch: false }

  // Keeps the glass off the text: the text must stay on the quiet sky at all times.
  const avoidText = (x: number, y: number, r: number): [number, number] => {
    const m = r * 1.14 + 16     // clear of the glass's contact shadow too, not just the glass
    const { l, t, r: rr, b } = textRect
    if (x > l - m && x < rr + m && y > t - m && y < b + m) {
      const pushes: [number, number][] = [[rr + m, y], [l - m, y], [x, b + m], [x, t - m]]
      let best = pushes[0]
      let bd = 1e12
      for (const p of pushes) {
        const inside = p[0] > r * 0.4 && p[0] < geo.w - r * 0.4 && p[1] > -r * 0.3 && p[1] < geo.h + r * 0.3
        const d = (p[0] - x) ** 2 + (p[1] - y) ** 2 + (inside ? 0 : 1e9)
        if (d < bd) {
          bd = d
          best = p
        }
      }
      return best
    }
    return [x, y]
  }

  // ------------------------------------------------------------------ input
  const toLocal = (e: PointerEvent) => {
    const hb = host.getBoundingClientRect()
    return [e.clientX - hb.left, e.clientY - hb.top] as const
  }
  host.addEventListener(
    'pointermove',
    e => {
      if (reduce) return
      const [x, y] = toLocal(e)
      pointer.x = x
      pointer.y = y
      pointer.active = true
      pointer.touch = e.pointerType === 'touch'
      pointer.last = performance.now()
    },
    { signal, passive: true },
  )
  host.addEventListener(
    'pointerdown',
    e => {
      if (reduce) return
      const [x, y] = toLocal(e)
      pointer.x = x
      pointer.y = y
      pointer.active = true
      pointer.touch = e.pointerType === 'touch'
      pointer.last = performance.now()
    },
    { signal, passive: true },
  )
  const release = () => {
    pointer.active = false
  }
  host.addEventListener('pointerleave', release, { signal, passive: true })
  host.addEventListener('pointercancel', release, { signal, passive: true })
  host.addEventListener(
    'pointerup',
    e => {
      if (e.pointerType === 'touch') release()
    },
    { signal, passive: true },
  )
  art.addEventListener(
    'click',
    e => {
      const hb = host.getBoundingClientRect()
      const [u, v] = cssToUv(e.clientX - hb.left, e.clientY - hb.top)
      startRun(u, v)
    },
    { signal },
  )
  play.addEventListener('click', () => startRun(manifest?.drift[0][0] ?? 0.5, manifest?.drift[0][1] ?? 0.56), { signal })
  play.hidden = reduce

  // ------------------------------------------------------------------ the run: a real simulated trail, anticipation, weight, a cheer
  type Run = { route: Route; start: number; i: number; phase: 'in' | 'run' | 'cheer' | 'out'; t: number; speed: number; face: number; drawn: number; fadeOut: number; dist: number }
  let run: Run | null = null
  let overDirty = false
  let idleRun = 6
  let ranOnce = false
  const parts: { x: number; y: number; vx: number; vy: number; life: number; c: number; s: number }[] = []
  const startRun = (u: number, v: number) => {
    if (!routes.length || reduce) return
    const px = u * 2560
    const py = v * 1440
    let best: Route = routes[0]
    let bi = 0
    let bd = 1e12
    for (const r of routes) {
      const stop = Math.max(0, r.n - 28)
      for (let i = 0; i < stop; i += 1) {
        const d = (r.x[i] - px) ** 2 + (r.y[i] - py) ** 2
        if (d < bd) {
          bd = d
          best = r
          bi = i
        }
      }
    }
    run = { route: best, start: bi, i: bi, phase: 'in', t: 0, speed: 0, face: 1, drawn: bi, fadeOut: 1, dist: 0 }
    parts.length = 0
    idleRun = 22
  }
  let lensFollow = false
  const CHEER_FRAMES = [8, 9, 10, 9]
  const FRAME_N = 12
  const IDLE_FRAME = 11

  const writeQuad = (at: number, x0: number, y0: number, x1: number, y1: number, s0: number, t0: number, s1: number, t1: number, c: number[], mode: number, depth: number) => {
    const v = (px: number, py: number, s: number, t: number) => {
      batch.set([px, py, s, t, c[0], c[1], c[2], c[3], mode, depth], at)
      at += STRIDE
    }
    v(x0, y0, s0, t0)
    v(x1, y0, s1, t0)
    v(x1, y1, s1, t1)
    v(x0, y0, s0, t0)
    v(x1, y1, s1, t1)
    v(x0, y1, s0, t1)
    return at
  }

  const drawOverlay = () => {
    let at = 0
    const r = run
    if (r) {
      const R = r.route
      const a0 = Math.max(r.start, 0)
      const a1 = Math.min(Math.ceil(r.drawn), R.n - 1)
      const alpha = r.fadeOut
      const pink = [250 / 255, 42 / 255, 111 / 255]
      const strip = (w0: number, opacity: number) => {
        for (let i = a0; i < a1 && at < batch.length - STRIDE * 12; i++) {
          const j = i + 1
          const dx = R.x[j] - R.x[i]
          const dy = R.y[j] - R.y[i]
          const n = Math.hypot(dx, dy) + 1e-3
          const nx = (-dy / n) * (w0 * R.s[i] / 12)
          const ny = (dx / n) * (w0 * R.s[i] / 12)
          const tail = sstep(a0, a0 + 12, i)
          const a = opacity * alpha * tail
          const c = [pink[0] * a, pink[1] * a, pink[2] * a, a]
          const d = R.d[i]
          const put = (px: number, py: number, s: number) => {
            batch.set([px, py, s, 0, c[0] / Math.max(a, 1e-3), c[1] / Math.max(a, 1e-3), c[2] / Math.max(a, 1e-3), a, 0, d], at)
            at += STRIDE
          }
          put(R.x[i] - nx, R.y[i] - ny, -1)
          put(R.x[i] + nx, R.y[i] + ny, 1)
          put(R.x[j] + nx, R.y[j] + ny, 1)
          put(R.x[i] - nx, R.y[i] - ny, -1)
          put(R.x[j] + nx, R.y[j] + ny, 1)
          put(R.x[j] - nx, R.y[j] - ny, -1)
        }
      }
      strip(11, 0.22)
      strip(4.6, 0.98)
      // the player
      const i = clamp(Math.floor(r.i), 0, R.n - 1)
      const i2 = Math.min(i + 1, R.n - 1)
      const fi = clamp(r.i - i)
      const fx = mix(R.x[i], R.x[i2], fi)
      const fy = mix(R.y[i], R.y[i2], fi)
      const s = R.s[i]
      const d = R.d[i]
      const charH = 4.6 * s * (256 / 150)
      let frame = 0
      let hop = 0
      let sx = 1
      let sy = 1
      let spriteA = 1
      if (r.phase === 'in') {
        // drops in from above, squashes, gathers itself
        const t = clamp(r.t / 0.52)
        const fall = 1 - t * t
        hop = fall * charH * 1.5
        spriteA = sstep(0, 0.2, r.t)
        const sq = sstep(0.5, 0.58, r.t) * (1 - sstep(0.62, 0.92, r.t))
        sx = 1 + 0.26 * sq
        sy = 1 - 0.3 * sq
        if (t < 1) sy *= 1.08
        frame = IDLE_FRAME
      } else if (r.phase === 'run') {
        frame = Math.floor(r.dist * 0.8) % 8
        hop = Math.abs(Math.sin(r.dist * 0.8 * Math.PI / 4)) * charH * 0.05
      } else if (r.phase === 'cheer') {
        const jump = Math.abs(Math.sin(r.t * 5.2))
        hop = jump * charH * 0.34
        const land = 1 - jump
        const sq = sstep(0.82, 1, land)
        sx = 1 + 0.16 * sq
        sy = 1 - 0.18 * sq + 0.08 * jump
        frame = CHEER_FRAMES[Math.floor(r.t * 6.5) % CHEER_FRAMES.length]
      } else {
        const t = clamp(r.t / 0.4)
        sx = 1 + 0.2 * Math.sin(t * Math.PI)
        sy = 1 - 0.9 * t
        spriteA = 1 - t
        frame = IDLE_FRAME
      }
      // ground shadow, offset away from the sun
      const shW = charH * 0.34 * (1 - clamp(hop / charH) * 0.5)
      const ox = charH * 0.07
      at = writeQuad(at, fx - shW + ox, fy - shW * 0.32 + charH * 0.015, fx + shW + ox, fy + shW * 0.32 + charH * 0.015, 0, 0, 1, 1, [0.0, 0.15, 0.17, 0.46 * spriteA], 2, d)
      // sprite: its feet sit about 89% of the way down the frame
      const fw = (charH * sx) / 2
      const fh = charH * sy
      const footAt = 0.89
      const top = fy - hop - fh * footAt
      const bot = top + fh
      const u0 = frame / FRAME_N
      const u1 = (frame + 1) / FRAME_N
      // Drawn in image space: in Arabic the whole overlay is mirrored with the art, so this already reads the right way round.
      const [s0, s1] = r.face >= 0 ? [u0, u1] : [u1, u0]
      at = writeQuad(at, fx - fw, top, fx + fw, bot, s0, 0, s1, 1, [1, 1, 1, spriteA], 1, d)
      // the moment at the flag
      if (r.phase === 'cheer' || r.phase === 'out') {
        const tr = r.phase === 'cheer' ? r.t : 2.6 + r.t
        for (let k = 0; k < 3; k++) {
          const q = clamp((tr - k * 0.28) / 1.1)
          if (q > 0 && q < 1) {
            const rad = charH * (0.4 + 2.4 * q)
            at = writeQuad(at, fx - rad, fy - rad * 0.46, fx + rad, fy + rad * 0.46, 0, 0, 1, 1, [pink[0], pink[1], pink[2], (1 - q) * 0.8], 3, 0)
          }
        }
        for (const p of parts) {
          const a = clamp(p.life * 2)
          const col = p.c < 0.5 ? pink : p.c < 0.8 ? [1, 0.82, 0.36] : [0.2, 0.86, 0.78]
          at = writeQuad(at, p.x - p.s, p.y - p.s, p.x + p.s, p.y + p.s, 0, 0, 1, 1, [col[0], col[1], col[2], a], 2, 0)
        }
      }
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo)
    gl.viewport(0, 0, OW, OH)
    gl.clearColor(0, 0, 0, 0)
    gl.clear(gl.COLOR_BUFFER_BIT)
    if (at > 0) {
      gl.useProgram(over)
      gl.bindVertexArray(vaoOver)
      gl.bindBuffer(gl.ARRAY_BUFFER, vbo)
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, batch.subarray(0, at))
      gl.enable(gl.BLEND)
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA)
      gl.drawArrays(gl.TRIANGLES, 0, at / STRIDE)
      gl.disable(gl.BLEND)
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  }

  const stepRun = (dt: number) => {
    const r = run
    if (!r) return
    const R = r.route
    r.t += dt
    if (r.phase === 'in') {
      r.drawn = r.start
      if (r.t > 0.95) {
        r.phase = 'run'
        r.t = 0
      }
    } else if (r.phase === 'run') {
      // accelerates out of the crouch, and eases back as it reaches the flag. One point is about 2.4 world units.
      const left = R.n - 1 - r.i
      const target = Math.min(1.15, 0.4 + r.t * 1.2) * (8 + 9 * sstep(0, 1, (R.n - r.start) / 130)) * sstep(0, 10, left + 2.5)
      r.speed = mix(r.speed, target, 1 - Math.exp(-dt * 6))
      r.i = Math.min(R.n - 1, r.i + r.speed * dt)
      r.dist += r.speed * dt
      r.drawn = r.i
      const j = Math.min(R.n - 1, Math.floor(r.i) + 2)
      const k = Math.max(0, Math.floor(r.i) - 1)
      const dx = R.x[j] - R.x[k]
      if (Math.abs(dx) > 0.8) r.face = dx > 0 ? 1 : -1
      if (r.i >= R.n - 1.5) {
        r.phase = 'cheer'
        r.t = 0
        for (let n = 0; n < 34; n++) {
          const a = Math.random() * Math.PI * 2
          const v = 16 + Math.random() * 42
          parts.push({ x: R.x[R.n - 1], y: R.y[R.n - 1] - 30, vx: Math.cos(a) * v, vy: -46 - Math.random() * 62 + Math.sin(a) * v * 0.3, life: 1 + Math.random() * 1.1, c: Math.random(), s: 1.8 + Math.random() * 2.4 })
        }
      }
    } else if (r.phase === 'cheer') {
      if (r.t > 2.6) {
        r.phase = 'out'
        r.t = 0
      }
    } else {
      r.fadeOut = 1 - clamp(r.t / 2.2)
      if (r.t > 2.3) {
        run = null
        lensFollow = false
      }
    }
    for (const p of parts) {
      p.vy += 92 * dt
      p.vx *= Math.exp(-dt * 1.2)
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.life -= dt
    }
    while (parts.length && parts[parts.length - 1].life <= 0) parts.pop()
    overDirty = true
  }

  // ------------------------------------------------------------------ labels
  let tagKey: Key | '' = ''
  let tagNext: Key | '' = ''
  let tagHold = 0
  const LABELS: Key[] = ['grid', 'wire', 'nav', 'trails', 'contours']
  const zoneFor = (u: number, v: number): Key => {
    const map = manifest?.labels
    if (!map) return 'grid'
    const j = clamp(Math.floor(u * 64), 0, 63)
    const i = clamp(Math.floor(v * 36), 0, 35)
    return LABELS[Number(map[i * 64 + j])] ?? 'grid'
  }

  // ------------------------------------------------------------------ the frame
  let time = 0
  const render = (dt: number, p: number) => {
    lastP = p
    if (!stack && !reduce) layout(p)
    else if (stack && Math.abs(geo.h - host.clientHeight) > 1) layout(p)

    // what's the lens after?
    const w = geo.w
    const hb = host.getBoundingClientRect()
    const viewTop = -hb.top
    const viewBot = viewTop + innerHeight
    const base = stack ? Math.min(w * 0.33, 180) : clamp(Math.min(w * 0.135, geo.h * 0.215), 110, 250)
    const scrollGrow = stack || reduce ? 0 : sstep(0.05, 0.75, p)
    let wantR = base * mix(1, 1.62, scrollGrow)
    if (!stack) wantR = Math.min(wantR, ((rtl ? textRect.l : w - textRect.r) - 20) * 0.5)
    lens.tr = wantR
    const nowT = performance.now()
    const engaged = pointer.active && (!pointer.touch || nowT - pointer.last < 2200) && nowT - pointer.last < 4200
    let tx: number
    let ty: number
    const stiff = engaged ? 150 : 16
    if (engaged) {
      tx = pointer.x
      ty = pointer.y
      lensFollow = false
    } else if (run) {
      // Nobody's steering, so the glass goes with the player.
      lensFollow = true
      const R = run.route
      const i = clamp(Math.floor(run.i + 7), 0, R.n - 1)
      ;[tx, ty] = uvToCss(R.x[i] / 2560, R.y[i] / 1440)
    } else {
      // On a phone with nothing happening, scrolling itself moves the glass along the route.
      lens.s += dt * (reduce ? 0 : 0.085) * (stack ? 0.8 : 1)
      const sp = lens.s + (stack ? p * 3.2 : p * 1.6)
      const uvp = reduce ? ([0.74, 0.45] as [number, number]) : driftAt(sp)
      ;[tx, ty] = uvToCss(uvp[0], uvp[1])
      if (stack) {
        // stay on screen while the section is on screen
        const midY = (viewTop + viewBot) / 2
        const lo = Math.max(textRect.b + lens.r + 10, viewTop + lens.r * 0.7)
        const hi = Math.min(geo.offY + geo.imgH * 0.9, viewBot - lens.r * 0.7)
        ty = hi > lo ? clamp(mix(ty, midY, 0.3), lo, hi) : Math.max(lo, geo.offY + geo.imgH * 0.6)
      }
    }
    if (stack) {
      // On a phone the text has its own ground, so the glass stays below it whoever is steering.
      tx = clamp(tx, lens.r * 0.72, w - lens.r * 0.72)
      ty = Math.max(ty, textRect.b + lens.r + 14)
    }
    if (!stack) {
      // keep most of the glass on screen, and off the text
      const keep = engaged ? 0.3 : 0.8
      tx = clamp(tx, lens.r * keep, w - lens.r * keep)
      ty = clamp(ty, lens.r * keep, geo.h - lens.r * keep)
      ;[tx, ty] = avoidText(tx, ty, lens.r)
    }
    if (!placed) {
      lens.x = tx
      lens.y = ty
      lens.r = wantR
      placed = true
    }
    // a heavy disc of glass: it follows with a little lag and settles
    const k = stiff
    const c = 2 * Math.sqrt(k) * 0.82
    const steps = 2
    for (let i = 0; i < steps; i++) {
      const h = dt / steps
      lens.vx += (k * (tx - lens.x) - c * lens.vx) * h
      lens.vy += (k * (ty - lens.y) - c * lens.vy) * h
      lens.x += lens.vx * h
      lens.y += lens.vy * h
    }
    lens.r += (lens.tr - lens.r) * (1 - Math.exp(-dt * 5))
    if (lensReady) lens.on = reduce ? 1 : Math.min(1, lens.on + dt / 0.8)
    if (reduce) lens.r = wantR
    const pop = reduce ? 1 : sstep(0, 1, lens.on)
    const popR = lens.r * mix(0.8, 1, 1 - (1 - pop) ** 3) * (1 + 0.05 * Math.sin(pop * Math.PI))

    if (!reduce) {
      time += dt
      // Idle: every so often a player sets off on its own, so someone who only scrolls still sees the run.
      if (lensReady && !run && section.getBoundingClientRect().top < innerHeight * 0.4) {
        idleRun -= dt
        if (idleRun < 0) {
          // from the dock the first time, then from wherever the glass happens to be
          const first = !ranOnce
          ranOnce = true
          const [u, v] = first && manifest ? manifest.drift[0] : cssToUv(lens.x, lens.y)
          startRun(u, v)
        }
      }
      if (run) stepRun(dt)
    }
    if (overDirty) {
      drawOverlay()
      overDirty = !!run
    }

    // ------------------------------------------------------------ uniforms
    gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    gl.viewport(0, 0, canvas.width, canvas.height)
    gl.useProgram(prog)
    gl.bindVertexArray(vaoMain)
    gl.uniform2f(U.uRes, canvas.width, canvas.height)
    gl.uniform2f(U.uOff, geo.offX * dpr, geo.offY * dpr)
    gl.uniform2f(U.uSize, geo.imgW * dpr, geo.imgH * dpr)
    gl.uniform3f(U.uLens, lens.x * dpr, lens.y * dpr, Math.max(popR, 1) * dpr)
    gl.uniform1f(U.uTime, time)
    const nx = (lens.x / Math.max(w, 1) - 0.5) * 2
    const ny = (lens.y / Math.max(geo.h, 1) - 0.5) * 2
    if (reduce) gl.uniform2f(U.uPar, 0, 0)
    else gl.uniform2f(U.uPar, (rtl ? -nx : nx) * 0.008, ny * 0.006 + (stack ? 0 : (p - 0.5) * 0.024))
    // Top and bottom of the stage are the page: the hero's blue while the hero is in view, white as the next section arrives.
    gl.uniform3f(U.uTop, 34 * dpr, Math.min(geo.h * 0.26, 240) * dpr, stack ? 0 : 1 - sstep(0.03, 0.26, p))
    gl.uniform3f(U.uBot, (geo.h - 90) * dpr, geo.h * dpr, stack ? 1 : sstep(0.72, 1, p))
    gl.uniform1f(U.uLensOn, lens.on)
    gl.uniform1f(U.uRimPx, (stack ? 13 : 21) * dpr)
    gl.uniform1f(U.uLod, Math.max(0, Math.log2(texW / Math.max(1, geo.imgW * dpr)) - 0.25))
    gl.drawArrays(gl.TRIANGLES, 0, 3)

    // ------------------------------------------------------------ the little label inside the glass
    if (lensReady && manifest) {
      const [u, v] = cssToUv(lens.x, lens.y)
      const key: Key = run && lensFollow ? 'run' : zoneFor(u, v)
      if (key !== tagNext) {
        tagNext = key
        tagHold = 0
      }
      tagHold += dt
      if (key !== tagKey && (tagHold > 0.5 || !tagKey || key === 'run')) {
        tagKey = key
        tag.classList.remove('is-on')
        window.setTimeout(() => {
          if (signal.aborted) return
          tagText.textContent = say(tagKey as Key)
          tag.classList.add('is-on')
        }, tagText.textContent ? 180 : 0)
      }
      const dy = popR * 0.895 - 30
      tag.style.transform = `translate3d(${lens.x.toFixed(1)}px, ${(lens.y + dy).toFixed(1)}px, 0) translate(-50%, 0)`
      tag.style.opacity = String(lens.on)
    }
  }

  let stillFrames = 0
  ctx.frame((p, dt) => {
    if (signal.aborted) return
    // Reduced motion: draw only when something changed, then rest.
    if (reduce) {
      if (dirty || !lensReady) stillFrames = 0
      dirty = false
      if (stillFrames++ > 6) return
      placed = false
    }
    render(reduce ? 0 : dt, p)
  })

  // ------------------------------------------------------------------ cleanup
  return () => {
    ro.disconnect()
    copy.classList.remove('xr-copy')
    const lose = gl.getExtension('WEBGL_lose_context')
    for (const t of Object.values(textures)) if (t) gl.deleteTexture(t)
    gl.deleteFramebuffer(fbo)
    gl.deleteBuffer(quad)
    gl.deleteBuffer(vbo)
    gl.deleteVertexArray(vaoMain)
    gl.deleteVertexArray(vaoOver)
    gl.deleteProgram(prog)
    gl.deleteProgram(over)
    lose?.loseContext()
    host.remove()
  }
}
